def _comments_enabled(path):
    p = path.replace('\\\\', '/')
    if p.endswith('index.html'):
        return False
    rel = '/'.join(p.split('/')[-2:])
    for pref in ('models/', 'pain/', 'blog/', 'news/', 'services/', 'catalog/'):
        if rel.startswith(pref):
            return True
    return False

