def clamp_desc(d, limit=165):
    d = (d or '').strip()
    if len(d) <= limit: return d
    cut = d[:limit]
    sp = cut.rfind(' ')
    if sp > limit - 40: cut = cut[:sp]
    return cut.rstrip(' ,.;:') + chr(8230)


def _inject_toc(body):
    """ÐÐ³Ð»Ð°Ð²Ð»ÐµÐ½Ð¸Ðµ Ð»Ð¾Ð½Ð³ÑÐ¸Ð´Ð°: id Ð½Ð° H2 + ÐºÐ¾Ð¼Ð¿Ð°ÐºÑÐ½ÑÐ¹ TOC-Ð±Ð¾ÐºÑ Ð¿Ð¾ÑÐ»Ðµ Ð»Ð¸Ð´Ð°.
    ÐÐ½ÑÐµÐºÑÐ¸Ñ ÑÐ¾Ð»ÑÐºÐ¾ ÐµÑÐ»Ð¸ Ð² ÑÐµÐ»Ðµ >=3 ÑÐ°Ð·Ð½ÑÑ H2."""
    try:
        if 'class="art-toc"' in body or 'art-tocmob' in body:
            return body
        h2_pat = re.compile(r'<h2((?:\s[^>]*)?)>(.*?)</h2>', re.S)
        found = h2_pat.findall(body)
        if len(found) < 3:
            return body
        items, seen = [], {}
        def _repl(m):
            attrs, inner = m.group(1), m.group(2)
            idm = re.search(r'id="([^"]+)"', attrs)
            if idm:
                sid = idm.group(1)
            else:
                text0 = re.sub(r'<[^>]+>', '', inner).strip()
                sid = 'anch-' + (slug(text0) or 'h2')[:48]
                if sid in seen:
                    seen[sid] += 1
                    sid = sid + '-' + str(seen[sid])
                else:
                    seen[sid] = 0
            text = re.sub(r'<[^>]+>', '', inner).strip()
            items.append((sid, text))
            if 'id=' in attrs:
                return m.group(0)
            return '<h2' + attrs + ' id="' + html.escape(sid) + '">' + inner + '</h2>'
        new_body = h2_pat.sub(_repl, body)
        toc = ('<div class="toc"><div class="toc-t">Ð¡Ð¾Ð´ÐµÑÐ¶Ð°Ð½Ð¸Ðµ</div><ol>'
               + ''.join('<li><a href="#' + html.escape(sid) + '">' + html.escape(text) + '</a></li>' for sid, text in items)
               + '</ol></div>')
        m = re.search(r'</p>', new_body)
        if m:
            return new_body[:m.end()] + toc + new_body[m.end():]
        return new_body + toc
    except Exception:
        return body

