    f_fact = ImageFont.truetype(fb, 30); f_foot = ImageFont.truetype(fb, 27)
    def _kw(s):
        if not s: return None
        mm = re.search(r'(?:Ð´Ð¾\s*)?~?\s*(\d[\d\s]{0,3}(?:\+\d+)?)\+?\s*ÐºÐÑ', s)
