def build_sitemap(slugs_model, news, vin_slugs, outdir='.'):
    urls = [SITE_DOMAIN+'/', SITE_DOMAIN+'/models/', SITE_DOMAIN+'/forum/', SITE_DOMAIN+'/pains.html', SITE_DOMAIN+'/about.html', SITE_DOMAIN+'/news/',
            SITE_DOMAIN+'/charging/', SITE_DOMAIN+'/vin/']
    urls += [SITE_DOMAIN+'/catalog/'] + [SITE_DOMAIN+'/catalog/'+p['slug']+'.html' for p in catalog.PRODUCTS]
    urls += [SITE_DOMAIN+'/services/', SITE_DOMAIN+'/services/ustanovka-stancii-v-garazhe.html', SITE_DOMAIN+'/services/moschnost-stancii.html', SITE_DOMAIN+'/services/tehobsluzhivanie-stanciy.html', SITE_DOMAIN+'/services/oshibki-ustanovki.html', SITE_DOMAIN+'/ev-services.html'] + [SITE_DOMAIN+'/services/'+s+'.html' for s in ['ustanovka-stancii','stanciya-gbt','stanciya-2v1','stanciya-type2','tehobsluzhivanie','uvelichenie-moshchnosti']]
    urls += [SITE_DOMAIN+'/blog/'] + [SITE_DOMAIN+'/blog/'+s+'.html' for s,_,_ in services.BLOG_ARTICLES]
    urls += [SITE_DOMAIN+'/blog/'+s+'.html' for s in ['zeekr-001-gbt-diff', 'li-l7-battery-heat', 'workersbee-vs-auxus', 'b2b-reglament-vydachi-ev', '800v-zaryadka-ev-rossiya', 'erekv-domashnyaya-zaryadka', 'sertifikaciya-ezs-rf-2026']]
    if SHOP_LIVE: urls += [SITE_DOMAIN+'/shop/digital/']
    urls += [SITE_DOMAIN+'/safety/'] + [SITE_DOMAIN+'/safety/'+s+'.html' for s,_,_ in services.SAFETY_ARTICLES]
    urls += [SITE_DOMAIN+'/cost/'+c[0]+'.html' for c in COST_MODELS]
    urls += [SITE_DOMAIN+'/b2b/']
    urls += [SITE_DOMAIN+'/calculator/']
    urls += [SITE_DOMAIN+'/baza-znaniy/', SITE_DOMAIN+'/baza-znaniy/zimniy-iznos-ev/', SITE_DOMAIN+'/baza-znaniy/magistrali-zimoy/', SITE_DOMAIN+'/routes/send-story/']
    urls += [SITE_DOMAIN+'/brands/'+bs+'.html' for bs in ('zeekr','geely','voyah','toyota','changan','evolute')]
    urls += [SITE_DOMAIN+'/open-data/']
    urls += [SITE_DOMAIN+'/quiz/']
    urls += [SITE_DOMAIN+'/app/']
    urls += [SITE_DOMAIN+u for _,u in CITY_URLS if os.path.exists(os.path.join(outdir, u.lstrip('/')))]
    urls += [SITE_DOMAIN+'/compare/']
    urls += [SITE_DOMAIN+'/'+s+'/' for s in slugs_model]
    urls += [SITE_DOMAIN+'/pain/'+s+'.html' for s,_,_,_ in PAIN_ARTICLES]
    urls += [SITE_DOMAIN+news_slug_page(it) for it in news]
    urls += [SITE_DOMAIN+'/'+s for s in vin_slugs]
    urls += [SITE_DOMAIN+'/'+tid+'.html' for tid,_,_,_ in _forum_seed()]
    lm = '<lastmod>' + BUILD_DATE + '</lastmod>'
    # R-09: Ð·Ð¸Ð¼Ð½Ð¸Ð¹ Ð¿ÑÐ¸Ð¾ÑÐ¸ÑÐµÑ â bridge/winter_seo.json (triggered=true, ÑÐ²ÐµÐ¶ÐµÐµ 48 Ñ) Ð¿Ð¾Ð´Ð½Ð¸Ð¼Ð°ÐµÑ Ð·Ð¸Ð¼Ð½Ð¸Ðµ URL.
    winter_boost = False
    try:
        if os.path.exists('bridge/winter_seo.json'):
            if time.time() - os.path.getmtime('bridge/winter_seo.json') < 48*3600:
                winter_boost = '"triggered": true' in open('bridge/winter_seo.json', encoding='utf-8').read()
    except Exception:
        pass
    WINTER_URLS = ['/blog/winter-ev-2026.html', '/blog/kvt-i-kvt-ch-raznica.html', '/blog/rasxod-zimoy-bortovoy-kompyuter.html', '/routes/', '/calculator/']
    prio = {}
    if winter_boost:
        for u in urls:
            path = u[len(SITE_DOMAIN):] if u.startswith(SITE_DOMAIN) else u
            prio[u] = 0.9 if path in WINTER_URLS else 0.5
        urls = [u for u in urls if prio.get(u) == 0.9] + [u for u in urls if prio.get(u) != 0.9]
    lm = '<lastmod>' + BUILD_DATE + '</lastmod>'
    def _url(u):
        pr = prio.get(u)
        p_tag = '<priority>' + str(pr) + '</priority>' if pr else ''
        return '<url><loc>' + u + '</loc>' + lm + p_tag + '</url>'
    return '<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + ''.join(_url(u) for u in urls) + '</urlset>'


